window.DEX_DATA["sources:backport-cc3a3268fa32cb38"]={"json":{"skins":[{"filename":"punkgirl.png"}],"names":[{"name":"诺米"},{"name":"艾薇儿"},{"name":"琼"},{"name":"佩内洛普"},{"name":"雪莉"}],"chat":[{"lines":[{"text":"我的发型不好打理，不过我能应付。"},{"text":"玩朋克总要付出点代价嘛。"}]},{"lines":[{"text":"打破规矩！谁还需要精灵球！"},{"text":"我都是徒手抓宝可梦的！"}]},{"lines":[{"text":"我的腕带还需要更多尖刺。"},{"text":"你知道去哪儿买吗？"}]},{"lines":[{"text":"你说我能训练胖丁唱朋克摇滚吗？"},{"text":"说不定还能给它弄个纹身，真酷。"}]}]}};
